exercise.solution:
use std::cell::RefCell;
use std::ops::Deref;
use std::rc::Rc;

enum Tree {
    Leaf,
    Node(Box<Tree>, Box<Tree>),
}

fn depth(tree: &Tree) -> u32 {
    match tree {
        Tree::Leaf => 1,
        Tree::Node(left, right) => {
            let l = depth(left);
            let r = depth(right);
            if l > r { l + 1 } else { r + 1 }
        }
    }
}

struct Guard {
    name: String,
    log: Rc<RefCell<Vec<String>>>,
}

impl Guard {
    fn new(name: &str, log: &Rc<RefCell<Vec<String>>>) -> Guard {
        log.borrow_mut().push(format!("opened {name}"));
        Guard { name: String::from(name), log: Rc::clone(log) }
    }
}

impl Drop for Guard {
    fn drop(&mut self) {
        self.log.borrow_mut().push(format!("closed {}", self.name));
    }
}

impl Deref for Guard {
    type Target = String;

    fn deref(&self) -> &String {
        &self.name
    }
}

fn shout(text: &str) -> String {
    text.to_uppercase()
}

fn main() {
    let leaf = Tree::Leaf;
    let pair = Tree::Node(Box::new(Tree::Leaf), Box::new(Tree::Leaf));
    let lopsided = Tree::Node(
        Box::new(Tree::Leaf),
        Box::new(Tree::Node(
            Box::new(Tree::Leaf),
            Box::new(Tree::Node(Box::new(Tree::Leaf), Box::new(Tree::Leaf))),
        )),
    );
    println!("depths: {} {} {}", depth(&leaf), depth(&pair), depth(&lopsided));

    let log = Rc::new(RefCell::new(Vec::new()));
    {
        let db = Guard::new("db", &log);
        let cache = Guard::new("cache", &log);
        println!("owners: {}", Rc::strong_count(&log));
        println!("{}", shout(&db));
        drop(cache);
        println!("owners: {}", Rc::strong_count(&log));
        log.borrow_mut().push(String::from("working"));
    }
    println!("owners: {}", Rc::strong_count(&log));
    for line in log.borrow().iter() {
        println!("{line}");
    }
}
